using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Security.Cryptography;
using EasyRoads3Dv3;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;

// Reference-only adapter. All road/connection geometry is generated by EasyRoads.
public static class UnityJunctionCapture {
    [Serializable]
    public class Road {
        public int   id;
        public bool  hubAtStart;
        public float width;
        public Vector3[] markers;
        public float[] strengths, rolls, widths;
        public float curbWidth, curbHeight, sidewalkWidth, sidewalkHeight;
        public bool  sidewalks;
    }
    [Serializable]
    public class Input {
        public string  schema, caseId, authorSha256, prefab;
        public int     version;
        public Vector3 hub;
        public Road[] roads;
        public bool  facilities;
        public float facilitySide, facilityUp;
        public Vector2[] facilityProfile;
        public string mappingLimit;
        public float  ringRadius, ringWidth;
        public Route[] routes;
    }
    [Serializable]
    public class Route {
        public int firstEdge, secondEdge;
    }
    [Serializable]
    public class PortFact {
        public int     roadId, portIndex;
        public int     sourceMarkers, generatedMarkers;
        public float   requestedWidth, actualWidth;
        public Vector3 port, endpoint;
        public float   endpointError;
    }
    [Serializable]
    public class MeshFact {
        public string  name;
        public bool    facility;
        public int     triangles;
        public Vector3 boundsCenter, boundsSize;
    }
    [Serializable]
    public class FootprintTriangle {
        public Vector2 a, b, c;
    }
    [Serializable]
    public class Footprint {
        public string                  schema  = "eve.tests.road-junction-footprint";
        public int                     version = 1;
        public List<FootprintTriangle> road = new List<FootprintTriangle>(), facility = new List<FootprintTriangle>();
    }
    [Serializable]
    public class Evidence {
        public string schema = "eve.tests.road-junction-reference", caseId, inputSha256, authorSha256, adapterSha256,
                      referenceAssemblySha256, authoringAdapterSha256, footprintSha256, unityVersion, scenePath, error,
                      mappingLimit;
        public int   version = 2, triangles, facilityTriangles, generatedConnections;
        public float measuredRingRadius, measuredRingWidth;
        public int   generatedWalks, explicitRoutes;
        public Vector3[] ports;
        public PortFact[] attachments;
        public MeshFact[] meshes;
        public string perspectiveSha256, topSha256;
    }
    public static void Run() {
        string[] args = Environment.GetCommandLineArgs();
        int index     = Array.IndexOf(args, "-junctionRoot");
        if (index < 0 || index + 1 >= args.Length)
            throw new ArgumentException("-junctionRoot required");
        if (QualitySettings.activeColorSpace != ColorSpace.Gamma)
            throw new InvalidDataException("Explicit Gamma project required");
        int failures = 0;
        foreach (string directory in Directory.GetDirectories(args[index + 1]).OrderBy(x => x)) {
            string path = Path.Combine(directory, "unity-input.json");
            if (!File.Exists(path))
                continue;
            Input input    = JsonUtility.FromJson<Input>(File.ReadAllText(path));
            var   evidence = new Evidence {
                caseId                 = input.caseId,
                inputSha256            = Hash(path),
                authorSha256           = input.authorSha256,
                adapterSha256          = Hash(Path.Combine(Application.dataPath, "Editor/UnityJunctionCapture.cs")),
                authoringAdapterSha256 = Hash(Path.Combine(Application.dataPath, "Editor/UnityJunctionAuthoring.cs")),
                referenceAssemblySha256 = Hash(typeof(ERRoad).Assembly.Location),
                unityVersion            = Application.unityVersion,
                mappingLimit            = input.mappingLimit
            };
            try {
                Generate(directory, input, evidence);
            } catch (Exception error) {
                failures++;
                evidence.error = error.ToString();
                Debug.LogError("JUNCTION_REFERENCE_FAILED " + input.caseId + " " + error);
            }
            File.WriteAllText(Path.Combine(directory, "unity-evidence.json"), JsonUtility.ToJson(evidence, true));
        }
        if (failures != 0)
            throw new InvalidDataException("Reference junction failures=" + failures);
        Debug.Log("JUNCTION_REFERENCE_COMPLETE");
    }
    private static void Generate(string directory, Input input, Evidence evidence) {
        if (input.schema != "eve.tests.road-junction-input" || input.version != 2 || input.roads.Length < 3)
            throw new InvalidDataException("Unsupported junction input");
        EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
        var network = new ERRoadNetwork();
        network.SetRaiseOffset(0f);
        SideObject   facility = input.facilities ? CreateFacility(network, input) : null;
        ERConnection prefab   = network.GetConnectionPrefabByName(input.prefab);
        if (prefab == null)
            throw new InvalidDataException("Missing reference prefab: " + input.prefab);
        ERConnection connection = network.InstantiateConnection(prefab, input.caseId, input.hub, Vector3.zero);
        if (connection == null)
            throw new InvalidDataException("Connection instantiation failed");
        if (input.ringRadius > 0)
            connection = UnityJunctionAuthoring.Ring(network, connection, input.ringRadius, input.ringWidth);
        Align(connection, input);
        if (input.ringRadius > 0) {
            var rb                      = connection.prefabScript.roundaboutScript;
            evidence.measuredRingRadius = rb.mainCenterPoints.Average(p => new Vector2(p.x, p.z).magnitude);
            evidence.measuredRingWidth  = rb.mainLeftPoints[0].magnitude - rb.mainRightPoints[0].magnitude;
        }
        evidence.ports                = connection.GetConnectionWorldPositions();
        evidence.generatedConnections = network.GetConnections().Length;
        var roads                     = new List<ERRoad>();
        var attachments               = new List<PortFact>();
        foreach (Road spec in input.roads) {
            Vector3[] markers = (Vector3[])spec.markers.Clone();
            int inner = spec.hubAtStart ? 0 : markers.Length - 1, outer = spec.hubAtStart ? markers.Length - 1 : 0;
            int port = connection.FindNearestConnectionIndex(markers[outer]);
            if (port < 0)
                throw new InvalidDataException("No free connection port for road " + spec.id);
            Vector3 world  = connection.GetConnectionWorldPosition(port);
            markers[inner] = world;
            network.AddRoadType();
            network.roadNetwork.roadTypes.Last().roadWidth = spec.width;
            ERRoadType roadType                            = network.GetRoadTypes().Last();
            ERRoad     road = network.CreateRoad("junction-road-" + spec.id, roadType, markers);
            if (road == null)
                throw new InvalidDataException("Road creation failed");
            road.SetTerrainDeformation(false);
            road.SetRandomBumpiness(0, 0, 15, 35);
            road.SetResolution(.375f, false);
            road.SetAngleThreshold(4, false);
            for (int m = 0; m < markers.Length; ++m) {
                road.SetSplineStrength(m, spec.strengths[m], false);
                road.SetMarkerTilting(spec.rolls[m], m);
                road.SetWidth(spec.width * spec.widths[m], m);
            }
            road.Refresh();
            bool attached =
                spec.hubAtStart ? road.ConnectToStart(connection, port) : road.ConnectToEnd(connection, port);
            if (!attached)
                throw new InvalidDataException("Port attachment rejected for road " + spec.id);
            Vector3[] connectedMarkers = road.GetMarkerPositions();
            Vector3 endpoint           = connectedMarkers[spec.hubAtStart ? 0 : connectedMarkers.Length - 1];
            world                      = connection.GetConnectionWorldPosition(port);
            float error                = Vector3.Distance(endpoint, world);
            Debug.Log("JUNCTION_ENDPOINT road=" + spec.id + " port=" + world.ToString("F6") +
                      " endpoint=" + endpoint.ToString("F6") + " delta=" + error);
            if (error > .001f)
                throw new InvalidDataException("Connected endpoint differs from the port");
            attachments.Add(new PortFact { roadId = spec.id, portIndex = port, port = world, endpoint = endpoint,
                                           endpointError = error });
            if (facility != null)
                Activate(network, road, facility, markers.Length);
            roads.Add(road);
        }
        if (facility != null) {
            network.UpdateSideObjects();
            network.roadNetwork.buildSOinEditMode = true;
            foreach (ERRoad road in roads) {
                road.roadScript.rebuildSos = true;
                road.Refresh();
            }
            network.roadNetwork.UpdateSideObjectsInScene();
        }
        network.BuildRoadNetwork(false, false, false, roads.ToArray());
        network.HideWhiteSurfaces(true);
        if (facility != null) {
            foreach (Route route in input.routes) {
                int a = Array.FindIndex(input.roads, r => r.id == route.firstEdge),
                    b = Array.FindIndex(input.roads, r => r.id == route.secondEdge);
                BuildRoute(network, input, roads[a], input.roads[a], roads[b], input.roads[b], route);
                evidence.explicitRoutes++;
            }
        }

        for (int i = 0; i < roads.Count; ++i)
            if (input.roads[i].sidewalks) {
                UnityJunctionAuthoring.Walk(network, roads[i], input.roads[i]);
                evidence.generatedWalks += 2;
            }
        for (int i = 0; i < roads.Count; ++i) {
            Road         spec  = input.roads[i];
            ERRoad       road  = roads[i];
            ERConnection owner = spec.hubAtStart ? road.GetConnectionAtStart() : road.GetConnectionAtEnd();
            if (owner == null)
                throw new InvalidDataException("Saved road has no connection owner");
            PortFact fact = attachments[i];
            fact.port     = connection.GetConnectionWorldPosition(fact.portIndex);
            if (Vector3.Distance(owner.GetConnectionWorldPosition(fact.portIndex), fact.port) > .001f)
                throw new InvalidDataException("Connection owner changed during build");
            Vector3[] markers     = road.GetMarkerPositions();
            fact.endpoint         = markers[spec.hubAtStart ? 0 : markers.Length - 1];
            fact.endpointError    = Vector3.Distance(fact.endpoint, fact.port);
            fact.sourceMarkers    = spec.markers.Length;
            fact.generatedMarkers = markers.Length;
            fact.requestedWidth   = spec.width;
            fact.actualWidth      = road.GetWidth();
            if (fact.endpointError > .001f)
                throw new InvalidDataException("Built terminal marker detached from port");
        }
        if (input.ringRadius > 0) {
            var rb                      = connection.prefabScript.roundaboutScript;
            evidence.measuredRingRadius = rb.mainCenterPoints.Average(p => new Vector2(p.x, p.z).magnitude);
            evidence.measuredRingWidth  = rb.mainLeftPoints.Average(p => new Vector2(p.x, p.z).magnitude) -
                                         rb.mainRightPoints.Average(p => new Vector2(p.x, p.z).magnitude);
            if (Mathf.Abs(evidence.measuredRingRadius - input.ringRadius) > .001f ||
                Mathf.Abs(evidence.measuredRingWidth - input.ringWidth) > .001f)
                throw new InvalidDataException("Final ring dimensions changed during connected-road build");
        }
        evidence.ports       = connection.GetConnectionWorldPositions();
        evidence.attachments = attachments.ToArray();
        var facilities       = new HashSet<MeshRenderer>(
            UnityEngine.Object.FindObjectsByType<ERSideObjectInstance>(FindObjectsSortMode.None)
                .SelectMany(s => s.GetComponentsInChildren<MeshRenderer>(true)));
        string folder = "Assets/RoadJunctionParity/" + input.caseId;
        Directory.CreateDirectory(folder);
        AssetDatabase.Refresh();
        Material asphalt = Asphalt(), rail = Rail();
        AssetDatabase.CreateAsset(asphalt, AssetDatabase.GenerateUniqueAssetPath(folder + "/asphalt.mat"));
        AssetDatabase.CreateAsset(rail, AssetDatabase.GenerateUniqueAssetPath(folder + "/facility.mat"));
        var footprint = new Footprint();
        var meshes    = new List<MeshFact>();
        var snapshots = new Dictionary<Mesh, Mesh>();
        foreach (MeshRenderer renderer in UnityEngine.Object.FindObjectsByType<MeshRenderer>(
                     FindObjectsSortMode.None)) {
            if (!renderer.enabled || !renderer.gameObject.activeInHierarchy)
                continue;
            if (renderer.sharedMaterials.Any(m => m != null && m.name == "surfaceMaterial")) {
                renderer.enabled = false;
                continue;
            }
            MeshFilter filter = renderer.GetComponent<MeshFilter>();
            if (filter == null || filter.sharedMesh == null)
                continue;
            bool isFacility = facilities.Contains(renderer);
            if (input.facilities) {
                Vector3[] vertices = filter.sharedMesh.vertices;
                int[] indices      = filter.sharedMesh.triangles;
                for (int t = 0; t < indices.Length; t += 3) {
                    Vector3 a = renderer.transform.TransformPoint(vertices[indices[t]]),
                            b = renderer.transform.TransformPoint(vertices[indices[t + 1]]),
                            c = renderer.transform.TransformPoint(vertices[indices[t + 2]]);
                    var tri   = new FootprintTriangle { a = new Vector2(a.x, a.z), b = new Vector2(b.x, b.z),
                                                      c = new Vector2(c.x, c.z) };
                    (isFacility ? footprint.facility : footprint.road).Add(tri);
                }
            }

            int count = filter.sharedMesh.triangles.Length / 3;
            evidence.triangles += count;
            if (isFacility)
                evidence.facilityTriangles += count;
            meshes.Add(new MeshFact { name = renderer.name, facility = isFacility, triangles = count,
                                      boundsCenter = renderer.bounds.center, boundsSize = renderer.bounds.size });
            renderer.sharedMaterials =
                Enumerable.Repeat(isFacility ? rail : asphalt, Math.Max(1, renderer.sharedMaterials.Length)).ToArray();
            renderer.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
            if (!snapshots.TryGetValue(filter.sharedMesh, out Mesh snapshot)) {
                snapshot = UnityEngine.Object.Instantiate(filter.sharedMesh);
                snapshots.Add(filter.sharedMesh, snapshot);
                AssetDatabase.CreateAsset(snapshot, AssetDatabase.GenerateUniqueAssetPath(folder + "/mesh.asset"));
            }
            filter.sharedMesh = snapshot;
        }
        if (input.facilities) {
            string footprintPath = Path.Combine(directory, "unity-footprint.json");
            File.WriteAllText(footprintPath, JsonUtility.ToJson(footprint, true));
            evidence.footprintSha256 = Hash(footprintPath);
        }
        if (evidence.triangles == 0 || (input.facilities && evidence.facilityTriangles == 0))
            throw new InvalidDataException("Missing generated meshes");
        evidence.meshes        = meshes.ToArray();
        Camera camera          = new GameObject("Junction perspective camera").AddComponent<Camera>();
        camera.clearFlags      = CameraClearFlags.SolidColor;
        camera.backgroundColor = new Color(.3f, .3f, .3f, 1);
        camera.fieldOfView     = 42;
        camera.nearClipPlane   = .1f;
        camera.farClipPlane    = 250;
        camera.allowHDR = camera.allowMSAA = false;
        Capture(camera, new Vector3(48, 36, -48), Vector3.up, Path.Combine(directory, "unity-perspective.png"));
        Capture(camera, new Vector3(0, 92, 0), Vector3.forward, Path.Combine(directory, "unity-top.png"));
        camera.transform.position = new Vector3(48, 36, -48);
        camera.transform.LookAt(new Vector3(0, 2, 0), Vector3.up);
        evidence.perspectiveSha256 = Hash(Path.Combine(directory, "unity-perspective.png"));
        evidence.topSha256         = Hash(Path.Combine(directory, "unity-top.png"));
        evidence.scenePath         = folder + "/reference.unity";
        AssetDatabase.SaveAssets();
        if (!EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),
                                          evidence.scenePath))
            throw new IOException("Scene save failed");
        Debug.Log("JUNCTION_REFERENCE_CASE " + input.caseId + " attachments=" + attachments.Count +
                  " triangles=" + evidence.triangles + " facility=" + evidence.facilityTriangles);
    }
    [Serializable]
    public class ReopenEvidence {
        public string schema  = "eve.tests.road-junction-scene-reopen", caseId, adapterSha256, sceneSha256, frameSha256;
        public int    version = 1, triangles;
        public bool   pixelsIdentical;
    }
    public static void VerifySaved() {
        string[] args = Environment.GetCommandLineArgs();
        int index     = Array.IndexOf(args, "-junctionRoot");
        if (index < 0 || index + 1 >= args.Length)
            throw new ArgumentException("-junctionRoot required");
        foreach (string directory in Directory.GetDirectories(args[index + 1]).OrderBy(x => x)) {
            string path = Path.Combine(directory, "unity-evidence.json");
            if (!File.Exists(path))
                continue;
            Evidence evidence = JsonUtility.FromJson<Evidence>(File.ReadAllText(path));
            if (!string.IsNullOrEmpty(evidence.error))
                throw new InvalidDataException(evidence.error);
            EditorSceneManager.OpenScene(evidence.scenePath, OpenSceneMode.Single);
            int triangles = 0;
            foreach (MeshRenderer renderer in UnityEngine.Object.FindObjectsByType<MeshRenderer>(
                         FindObjectsSortMode.None)) {
                if (!renderer.enabled || !renderer.gameObject.activeInHierarchy)
                    continue;
                MeshFilter filter = renderer.GetComponent<MeshFilter>();
                if (filter == null || filter.sharedMesh == null)
                    continue;
                triangles += filter.sharedMesh.triangles.Length / 3;
            }
            if (triangles != evidence.triangles)
                throw new InvalidDataException("Reopened scene geometry differs: " + evidence.caseId);
            Camera camera = GameObject.Find("Junction perspective camera").GetComponent<Camera>();
            string frame  = Path.Combine(directory, "unity-reopened-perspective.png");
            Capture(camera, new Vector3(48, 36, -48), Vector3.up, frame);
            string frameHash = Hash(frame);
            if (frameHash != evidence.perspectiveSha256)
                throw new InvalidDataException("Reopened frame differs: " + evidence.caseId);
            File.WriteAllText(
                Path.Combine(directory, "unity-reopen.json"),
                JsonUtility.ToJson(new ReopenEvidence { caseId        = evidence.caseId,
                                                        adapterSha256 = Hash(Path.Combine(
                                                            Application.dataPath, "Editor/UnityJunctionCapture.cs")),
                                                        sceneSha256 = Hash(evidence.scenePath), frameSha256 = frameHash,
                                                        triangles = triangles, pixelsIdentical = true },
                                   true));
            Debug.Log("JUNCTION_REOPEN_CASE " + evidence.caseId + " triangles=" + triangles);
        }
        Debug.Log("JUNCTION_REOPEN_COMPLETE");
    }
    private static void Align(ERConnection connection, Input input) {
        Vector3[] ports = connection.GetConnectionWorldPositions();
        float best = float.PositiveInfinity, yaw = 0;
        foreach (float angle in new[] { 0f, 45f, 90f, 135f, 180f, 225f, 270f, 315f }) {
            float score = 0;
            foreach (Road road in input.roads) {
                Vector3 direction =
                    (road.markers[road.hubAtStart ? road.markers.Length - 1 : 0] - input.hub).normalized;
                float nearest = -1;
                foreach (Vector3 port in ports)
                    nearest = Mathf.Max(
                        nearest, Vector3.Dot(direction, Quaternion.Euler(0, angle, 0) * (port - input.hub).normalized));
                score += 1 - nearest;
            }
            if (score < best) {
                best = score;
                yaw  = angle;
            }
        }
        if (best > .01f)
            throw new InvalidDataException("Prefab cannot align authored arm directions");
        connection.SetRotation(new Vector3(0, yaw, 0));
    }
    private static void BuildRoute(ERRoadNetwork network, Input input, ERRoad first, Road firstSpec, ERRoad second,
                                   Road secondSpec, Route route) {
        Vector3[] a = first.GetMarkerPositions(), b = second.GetMarkerPositions();
        Vector3 fa = (a[a.Length - 1] - a[0]).normalized, fb = (b[b.Length - 1] - b[0]).normalized;
        Vector3 p0 = a[firstSpec.hubAtStart ? 0 : a.Length - 1] + Vector3.Cross(Vector3.up, fa) * input.facilitySide;
        Vector3 p1 = b[secondSpec.hubAtStart ? 0 : b.Length - 1] + Vector3.Cross(Vector3.up, fb) * input.facilitySide;
        Vector3 ta = firstSpec.hubAtStart ? -fa : fa, tb = secondSpec.hubAtStart ? fb : -fb;
        float   guard = Vector3.Distance(p0, p1);
        network.AddRoadType();
        network.roadNetwork.roadTypes.Last().roadWidth = .2f;
        ERRoad carrier =
            network.CreateRoad("explicit-facility-route-" + route.firstEdge + "-" + route.secondEdge,
                               network.GetRoadTypes().Last(), new[] { p0 - ta * .05f, p0, p1, p1 + tb * .05f });
        carrier.SetTerrainDeformation(false);
        carrier.SetRandomBumpiness(0, 0, 15, 35);
        carrier.SetResolution(.15f, false);
        carrier.SetMarkerControlType(0, ERMarkerControlType.StraightXZY);
        carrier.SetMarkerControlType(2, ERMarkerControlType.StraightXZY);
        // SDK straight-adjacent handles scale with projected chord, whereas
        // the native route author contract uses Euclidean chord / 3.
        Vector3 delta       = p1 - p0;
        float   projection0 = Mathf.Abs(Vector3.Dot(delta, ta)), projection1 = Mathf.Abs(Vector3.Dot(delta, tb));
        if (projection0 < .001f || projection1 < .001f)
            throw new InvalidDataException("Unbounded SDK route tangent projection");
        carrier.SetSplineStrength(1, guard / (2 * projection0), false);
        carrier.SetSplineStrength(2, guard / (2 * projection1), false);
        carrier.Refresh();
        float old                   = input.facilitySide;
        input.facilitySide          = 0;
        SideObject shape            = CreateFacility(network, input);
        input.facilitySide          = old;
        shape.name                  = "explicit-route-shape-" + route.firstEdge + "-" + route.secondEdge;
        shape.id                    = 940000 + route.firstEdge;
        shape.continueOnConnections = false;
        // Joined route ends do not need caps. Keep short, active guide segments:
        // an inactive endpoint makes this SDK emit a zero-position last row.
        shape.startEndCaps = false;
        shape.startCapTris.Clear();
        shape.startCapTrisMirrored.Clear();
        shape.m_distance      = 1f;
        shape.averageDistance = true;
        Activate(network, carrier, shape, 4);
        carrier.roadScript.rebuildSos = true;
        carrier.Refresh();
        network.roadNetwork.UpdateSideObjectsInScene();
        carrier.roadScript.GetComponent<MeshRenderer>().enabled = false;
        int count = carrier.roadScript.GetComponentsInChildren<ERSideObjectInstance>()
                        .SelectMany(i => i.GetComponentsInChildren<MeshFilter>())
                        .Sum(f => f.sharedMesh == null ? 0 : f.sharedMesh.triangles.Length / 3);
        if (count == 0)
            throw new InvalidDataException("Empty explicit SDK facility route");
        Debug.Log("JUNCTION_EXPLICIT_ROUTE first=" + route.firstEdge + " second=" + route.secondEdge +
                  " triangles=" + count + " p0=" + p0 + " p1=" + p1);
    }
    private static SideObject CreateFacility(ERRoadNetwork network, Input input) {
        var so                   = ScriptableObject.CreateInstance<SideObject>();
        so.name                  = "junction-rail";
        so.id                    = 920001;
        so.objectType            = 1;
        so.position              = 0;
        so.relativeToCenter      = true;
        so.xPosition             = input.facilitySide;
        so.yPosition             = input.facilityUp;
        so.align                 = 2;
        so.snapToTerrain         = false;
        so.combine               = false;
        so.combineInstantiated   = false;
        so.continueOnConnections = true;
        so.autoGenerate          = false;
        so.minSectionLength      = 0;
        so.maxVertices           = 65000;
        so.startEndCaps          = true;
        so.nodeList              = input.facilityProfile.ToList();
        so.nodeListMirrored      = input.facilityProfile.ToList();
        so.hardEdge              = so.nodeList
                          .Select(
                              _ => true)
                          .ToList();
        so.hardEdgeMirrored = new List<bool>(so.hardEdge);
        so.uvs              = so.nodeList.Select(p => p.x).ToList();
        so.uvsMirrored      = new List<float>(so.uvs);
        so.uvDistances   = so.nodeList.Select((p, i) => i == 0 ? 0f : Vector2.Distance(p, so.nodeList[i - 1])).ToList();
        so.totalDistance = so.uvDistances.Sum();
        so.snapList      = so.nodeList
                          .Select(
                              _ => false)
                          .ToList();
        so.snapWeightList = so.nodeList
                                .Select(
                                    _ => 0f)
                                .ToList();
        so.colorList = so.nodeList
                           .Select(
                               _ => Color.white)
                           .ToList();
        so.startCapTris                              = new List<int> { 0, 1, 2, 0, 2, 3 };
        so.startCapTrisMirrored                      = new List<int>(so.startCapTris);
        so.startCapUVs                               = so.nodeList.ToList();
        so.endCapUVs                                 = so.nodeList.ToList();
        so.material                                  = new Material(Shader.Find("Unlit/Color"));
        GameObject carrier                           = GameObject.CreatePrimitive(PrimitiveType.Cube);
        carrier.name                                 = "hidden author shape cache carrier";
        carrier.GetComponent<MeshRenderer>().enabled = false;
        so.meshObjects.Add(new ERMesh(carrier, so, 0, carrier.transform, Vector3.one,
                                      carrier.GetComponent<MeshFilter>().sharedMesh, so.material, 0, 1, false));
        FieldInfo owner = network.roadNetwork.GetType()
                              .GetFields(BindingFlags.Public | BindingFlags.Instance)
                              .Single(f => f.FieldType == typeof(List<SideObject>));
        ((List<SideObject>)owner.GetValue(network.roadNetwork)).Add(so);
        return so;
    }
    private static ERSORoadExt Activate(ERRoadNetwork network, ERRoad road, SideObject so, int markers) {
        ERSORoadExt ext = ERSORoadExt.CreateInstance(so);
        ext.active = ext.markerActive = true;
        road.SetSideObjects(new List<ERSORoadExt> { ext }, so.id);
        road.roadScript.soData.Add(new ERSORoad(so));
        network.SynchSideObjects(false);
        road.SetMarkerSideObjects();
        foreach (ERMarkerExt marker in road.roadScript.markersExt) {
            if (marker.soData == null)
                marker.soData = new List<ERSOMarkerExt>();
            if (!marker.soData.Any(s => s.id == so.id))
                marker.soData.Add(ERSOMarkerExt.CreateInstance(so, true));
            marker.soData.First(s => s.id == so.id).nodeList = new List<Vector2>(so.nodeList);
        }
        bool changed = road.SideObjectSetActive(so, true);
        Debug.Log("JUNCTION_FACILITY_ACTIVATE changed=" + changed);
        if (!road.GetSideObjectActiveState(so))
            throw new InvalidDataException("Inactive facility");
        for (int m = 0; m < markers; ++m) {
            bool update = road.SideObjectMarkerSetActive(so, m, true, ERRoadSide.Left, false);
            Debug.Log("JUNCTION_FACILITY_MARKER changed=" + update);
        }
        return road.roadScript.soDataExt.Single(s => s.id == so.id);
    }
    private static Material Asphalt() {
        var material = new Material(Shader.Find("RoadParity/AsphaltCommonV1"));
        material.SetTexture("roadColor",
                            AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/RoadMaterialParity/road-color.jpg"));
        material.SetTexture("roadNormal",
                            AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/RoadMaterialParity/road-normal.jpg"));
        return material;
    }
    private static Material Rail() {
        const string folder = "Assets/RoadJunctionParity";
        Directory.CreateDirectory(folder);
        var material = new Material(Shader.Find("RoadParity/AsphaltCommonV1"));
        foreach (bool normal in new[] { false, true }) {
            string path  = folder + (normal ? "/flat.png" : "/rail.png");
            var    image = new Texture2D(4, 4, TextureFormat.RGB24, false, true);
            Color  c     = normal ? new Color(128 / 255f, 128 / 255f, 1) : new Color(242 / 255f, 186 / 255f, 76 / 255f);
            image.SetPixels(Enumerable.Repeat(c, 16).ToArray());
            image.Apply();
            File.WriteAllBytes(path, image.EncodeToPNG());
            UnityEngine.Object.DestroyImmediate(image);
            AssetDatabase.ImportAsset(path);
            var importer                = (TextureImporter)AssetImporter.GetAtPath(path);
            importer.textureType        = TextureImporterType.Default;
            importer.sRGBTexture        = false;
            importer.mipmapEnabled      = false;
            importer.textureCompression = TextureImporterCompression.Uncompressed;
            importer.SaveAndReimport();
            material.SetTexture(normal ? "roadNormal" : "roadColor", AssetDatabase.LoadAssetAtPath<Texture2D>(path));
        }
        return material;
    }
    private static void Capture(Camera camera, Vector3 eye, Vector3 up, string path) {
        camera.transform.position = eye;
        camera.transform.LookAt(new Vector3(0, 2, 0), up);
        camera.aspect          = 1280f / 720;
        RenderTexture texture  = RenderTexture.GetTemporary(1280, 720, 24, RenderTextureFormat.ARGB32),
                      previous = RenderTexture.active;
        var pixels             = new Texture2D(1280, 720, TextureFormat.RGB24, false);
        try {
            camera.targetTexture = texture;
            camera.Render();
            RenderTexture.active = texture;
            pixels.ReadPixels(new Rect(0, 0, 1280, 720), 0, 0);
            pixels.Apply();
            File.WriteAllBytes(path, pixels.EncodeToPNG());
        } finally {
            camera.targetTexture = null;
            RenderTexture.active = previous;
            UnityEngine.Object.DestroyImmediate(pixels);
            RenderTexture.ReleaseTemporary(texture);
        }
    }
    private static string Hash(string path) {
        using (var h = SHA256.Create()) return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(path)))
            .Replace("-", "")
            .ToLowerInvariant();
    }
